<script setup lang="ts">
import {computed,ref,watch} from 'vue';import PublicNetwork from './PublicNetwork.vue';const publicOpen=ref(false);
import {api,download,type State,type Worker,type Pipe,type Node} from '../api';
import {Route,Layers,MapPin,Plus,Minus,Maximize,Upload,Download,Check,ArrowRight,MousePointer2,X,Save} from 'lucide-vue-next';
const props=defineProps<{state:State;workers:Worker[];compact?:boolean}>();const emit=defineEmits<{refresh:[];created:[id:string]}>();
const mode=ref('plan'),start=ref('J01'),end=ref('J06'),via=ref(''),avoid=ref(''),diameter=ref(0),flow=ref(false),worker=ref('worker'),device=ref('PP-001'),name=ref('片区排水管道巡检');
const busy=ref(false),error=ref(''),notice=ref(''),chosen=ref(''),hover=ref<{id:string;x:number;y:number}|null>(null),pinned=ref(false),pointMode=ref('start');
const preview=ref<{pipes:string[];length:number;legs:{start:string;end:string;length:number;pipes:string[]}[]}|null>(null);
const source=ref(''),importText=ref(''),sample=ref(true),baseline=ref(false),showLabels=ref(true),fileInput=ref<HTMLInputElement|null>(null);
const zoom=ref(1),pan=ref({x:0,y:0}),drag=ref<{x:number;y:number;px:number;py:number}|null>(null);
const coords=computed(()=>{const geo=props.state.nodes.length>0&&props.state.nodes.every(n=>n.lng!=null&&n.lat!=null);const merc=(lng:number,lat:number)=>({x:(lng+180)/360*256*Math.pow(2,17),y:(1-Math.log(Math.tan(lat*Math.PI/180)+1/Math.cos(lat*Math.PI/180))/Math.PI)/2*256*Math.pow(2,17)});const out=new Map<string,{x:number;y:number}>();props.state.nodes.forEach(n=>out.set(n.id,geo?merc(n.lng!,n.lat!):{x:n.x,y:n.y}));return {geo,out};});
const bounds=computed(()=>{const v=[...coords.value.out.values()];if(!v.length)return{x:0,y:0,w:960,h:570};const xs=v.map(n=>n.x),ys=v.map(n=>n.y),xmin=Math.min(...xs),ymin=Math.min(...ys),w=Math.max(200,Math.max(...xs)-xmin),h=Math.max(180,Math.max(...ys)-ymin);return{x:xmin-w*.15,y:ymin-h*.25,w:w*1.3,h:h*1.5};});
const view=computed(()=>{const b=bounds.value;return`${b.x+pan.value.x} ${b.y+pan.value.y} ${b.w/zoom.value} ${b.h/zoom.value}`;});
const tiles=computed(()=>{if(!baseline.value||!coords.value.geo)return[];const b=bounds.value;const x0=Math.floor(b.x/256),y0=Math.floor(b.y/256),x1=Math.floor((b.x+b.w)/256),y1=Math.floor((b.y+b.h)/256);if((x1-x0+1)*(y1-y0+1)>64)return[];const out=[];for(let x=x0;x<=x1;x++)for(let y=y0;y<=y1;y++)out.push({x:x*256,y:y*256,url:`https://tile.openstreetmap.org/17/${x}/${y}.png`});return out;});
const at=(id:string)=>coords.value.out.get(id)||{x:0,y:0};
const pipe=computed(()=>props.state.pipes.find(p=>p.id===chosen.value));const tip=computed(()=>props.state.pipes.find(p=>p.id===hover.value?.id));
const selected=computed(()=>{const p=pipe.value;return p?{...p}:null;});const editLength=ref(0),editDiameter=ref(200),editStatus=ref('normal'),editMaterial=ref('PVC-U'),editDirected=ref(false);
watch(()=>JSON.stringify(pipe.value),()=>{const p=pipe.value;if(p){editLength.value=p.length;editDiameter.value=p.diameter;editStatus.value=p.status;editMaterial.value=p.material||'PVC-U';editDirected.value=!!p.directed;}});
watch(()=>props.state.networkSource,s=>{source.value=s;sample.value=props.state.demo;},{immediate:true});
watch([start,end,via,avoid,diameter,flow,()=>JSON.stringify([props.state.pipes,props.state.nodes])],()=>preview.value=null);
const list=(s:string)=>s.split(/[，,\s]+/).map(x=>x.trim()).filter(Boolean);
async function execute(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function input(){return{start:start.value,end:end.value,via:list(via.value),avoid:list(avoid.value),minDiameter:diameter.value,flowOnly:flow.value};}
async function plan(){await execute(async()=>{preview.value=await api('/routes/preview',input());notice.value='路线计算完成';});}
async function create(){await execute(async()=>{const t=await api<{id:string}>('/tasks',{...input(),name:name.value,worker:worker.value,device:device.value});notice.value='巡检任务已保存，等待审核';emit('created',t.id);emit('refresh');});}
function tooltip(e:MouseEvent,p:Pipe,pin=false){if(pinned.value&&!pin)return;hover.value={id:p.id,x:Math.max(12,Math.min(e.clientX+18,window.innerWidth-310)),y:Math.max(12,Math.min(e.clientY+16,window.innerHeight-265))};if(pin){chosen.value=p.id;pinned.value=true;}}
function chooseNode(id:string){if(pointMode.value==='start'){start.value=id;pointMode.value='end';}else if(pointMode.value==='end'){end.value=id;}else{via.value=[...list(via.value),id].join(', ');}}
function resetView(){zoom.value=1;pan.value={x:0,y:0};}
function move(e:MouseEvent){if(!drag.value)return;const svg=e.currentTarget as SVGSVGElement;const ratio=bounds.value.w/zoom.value/svg.getBoundingClientRect().width;pan.value={x:drag.value.px-(e.clientX-drag.value.x)*ratio,y:drag.value.py-(e.clientY-drag.value.y)*ratio};}
async function savePipe(){await execute(async()=>{const pipes=props.state.pipes.map(p=>p.id===chosen.value?{...p,length:editLength.value,diameter:editDiameter.value,status:editStatus.value,material:editMaterial.value,directed:editDirected.value}:p);await api('/network',{nodes:props.state.nodes,pipes,source:source.value,demo:sample.value},'PUT');notice.value='管段资料已保存';emit('refresh');});}
function exportNetwork(){download('管脉探微-管网资料.json',{nodes:props.state.nodes,pipes:props.state.pipes,source:props.state.networkSource,demo:props.state.demo});}
function exportGeo(){if(!coords.value.geo){error.value='当前管网未登记经纬度，请先补充测绘坐标后导出GeoJSON。';return;}download('管网.geojson',{type:'FeatureCollection',source:props.state.networkSource,demo:props.state.demo,features:[...props.state.nodes.map(n=>({type:'Feature',geometry:{type:'Point',coordinates:[n.lng,n.lat]},properties:{id:n.id,label:n.label}})),...props.state.pipes.map(p=>({type:'Feature',geometry:{type:'LineString',coordinates:[props.state.nodes.find(n=>n.id===p.from)!,props.state.nodes.find(n=>n.id===p.to)!].map(n=>[n.lng,n.lat])},properties:p}))]});}
interface Feature {type:string;geometry:{type:string;coordinates:number[]|number[][]};properties:Record<string,unknown>}
function parseNetwork(text:string){const v=JSON.parse(text);if(v.nodes&&v.pipes)return{nodes:v.nodes as Node[],pipes:v.pipes as Pipe[],source:String(v.source||source.value),demo:v.demo!==false};if(v.type!=='FeatureCollection'||!Array.isArray(v.features))throw Error('请上传管网JSON或GeoJSON FeatureCollection');const nodes:Node[]=[],pipes:Pipe[]=[];const features=v.features as Feature[];for(const f of features){if(f.geometry.type==='Point'){const c=f.geometry.coordinates as number[];nodes.push({id:String(f.properties.id||''),label:String(f.properties.label||f.properties.name||f.properties.id||''),x:0,y:0,lng:c[0],lat:c[1]});}}for(const f of features){if(f.geometry.type!=='LineString')continue;const p=f.properties,c=f.geometry.coordinates as number[][];const closest=(point:number[])=>nodes.find(n=>Math.abs(n.lng!-point[0])<.000001&&Math.abs(n.lat!-point[1])<.000001)?.id;const from=String(p.from||closest(c[0])||''),to=String(p.to||closest(c[c.length-1])||'');if(!from||!to)throw Error('每条管线需有from/to，或端点坐标与检查井匹配');if(!p.length)throw Error('管线需填写经核验的length米值');pipes.push({id:String(p.id||''),from,to,length:Number(p.length),diameter:Number(p.diameter),status:String(p.status||'normal'),directed:p.directed===true,material:String(p.material||'')});}if(nodes.length<2||!pipes.length)throw Error('GeoJSON需同时包含检查井Point和管段LineString');return{nodes,pipes,source:String(v.source||source.value),demo:v.demo!==false};}
async function loadFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>5*1024*1024){error.value='文件不超过5MB';return;}importText.value=await f.text();try{const n=parseNetwork(importText.value);source.value=n.source;sample.value=n.demo;notice.value=`已读取${n.nodes.length}座井、${n.pipes.length}条管线，确认后导入`;error.value='';}catch(e){error.value=(e as Error).message;}if(fileInput.value)fileInput.value.value='';}
async function importNetwork(){if(!confirm('将更新当前片区管网，已关联任务的井与管段编号需要保留。是否继续？'))return;await execute(async()=>{const n=parseNetwork(importText.value);await api('/network',{...n,source:source.value,demo:sample.value},'PUT');notice.value='管网已导入并保存';importText.value='';resetView();emit('refresh');});}
async function expand(){if(!confirm('将保留现有管段，并加入一组明确标记为示例的支路。是否继续？'))return;await execute(async()=>{const nodes=[...props.state.nodes],pipes=[...props.state.pipes];for(let y=0;y<4;y++)for(let x=0;x<6;x++){const id=`S${y}${x}`;if(!nodes.some(n=>n.id===id))nodes.push({id,x:50+x*180,y:550+y*130,label:`${['北','中','南','汇流'][y]}区${x+1}号检查井`});if(x){const pid=`SH${y}${x}`;if(!pipes.some(p=>p.id===pid))pipes.push({id:pid,from:`S${y}${x-1}`,to:id,length:30+(x*11+y*7)%35,diameter:[200,250,300][(x+y)%3],status:x===3&&y===2?'blocked':'normal',material:'PVC-U',directed:false});}if(y){const pid=`SV${y}${x}`;if(!pipes.some(p=>p.id===pid))pipes.push({id:pid,from:`S${y-1}${x}`,to:id,length:28+(x*9+y*5)%25,diameter:250,status:'normal',material:'PVC-U',directed:false});}}if(nodes.some(n=>n.id==='J04')&&!pipes.some(p=>p.id==='SC01'))pipes.push({id:'SC01',from:'J04',to:'S00',length:36,diameter:200,status:'normal',material:'PVC-U',directed:false});await api('/network',{nodes,pipes,source:'园区支路示例数据（用于操作与路径计算）',demo:true},'PUT');notice.value='支路示例已加入，可在图中选择任意井计算路径';resetView();emit('refresh');});}
</script>
<template><div class="network-workspace"><div class="workspace-toolbar"><div><span class="data-label">{{state.demo?'示例管网':'管网档案'}}</span><strong>{{state.nodes.length}} 座检查井 · {{state.pipes.length}} 条管段</strong><small>{{state.networkSource}}</small></div><div class="button-group"><button class="outline" @click="publicOpen=true">公开管网参考</button><button class="outline" @click="exportNetwork"><Download :size="16"/>导出资料</button><button v-if="!compact" class="outline" @click="mode='data'"><Upload :size="16"/>导入 / 管理</button></div></div><div v-if="error" class="error" role="alert">{{error}}</div><div v-if="notice" class="notice" @click="notice=''">{{notice}}<Check :size="16"/></div><div :class="['network-layout',{compact}]"><section class="panel network-map"><div class="map-topbar"><div class="button-group"><button :class="{on:pointMode==='start'}" @click="pointMode='start'">选起点</button><button :class="{on:pointMode==='end'}" @click="pointMode='end'">选终点</button><button :class="{on:pointMode==='via'}" @click="pointMode='via'">选途经井</button></div><span><MousePointer2 :size="14"/>点击检查井设置路线，悬停管段查看资料</span></div><div class="network-canvas"><svg :viewBox="view" @mousedown.self="e=>drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y}" @mousemove="move" @mouseup="drag=null" @mouseleave="drag=null" @wheel.prevent="e=>zoom=Math.max(.5,Math.min(4,zoom*(e.deltaY>0?.9:1.1)))" aria-label="交互式管网图"><defs><pattern id="dots2" width="30" height="30" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#b5c8c1"/></pattern><marker id="arrow2" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#348777"/></marker></defs><rect :x="bounds.x-10000" :y="bounds.y-10000" width="30000" height="30000" fill="#edf3ef" @mousedown="e=>drag={x:e.clientX,y:e.clientY,px:pan.x,py:pan.y}" @click="()=>{hover=null;pinned=false;}"/><rect :x="bounds.x" :y="bounds.y" :width="bounds.w" :height="bounds.h" fill="url(#dots2)" pointer-events="none"/><image v-for="t in tiles" :key="t.url" :href="t.url" :x="t.x" :y="t.y" width="256" height="256" opacity=".75" pointer-events="none"/><g v-for="p in state.pipes" :key="p.id" class="network-edge" @mouseenter="e=>tooltip(e,p)" @mousemove="e=>tooltip(e,p)" @mouseleave="()=>{if(!pinned)hover=null;}" @click.stop="e=>tooltip(e,p,true)" tabindex="0" @focus="chosen=p.id" @keydown.enter="chosen=p.id"><line :x1="at(p.from).x" :y1="at(p.from).y" :x2="at(p.to).x" :y2="at(p.to).y" stroke="transparent" stroke-width="20" vector-effect="non-scaling-stroke"/><line :x1="at(p.from).x" :y1="at(p.from).y" :x2="at(p.to).x" :y2="at(p.to).y" :stroke="preview?.pipes.includes(p.id)?'#d08a36':chosen===p.id?'#146fbe':p.status==='blocked'?'#9baba8':p.status==='attention'?'#bc9654':'#579d8d'" :stroke-width="preview?.pipes.includes(p.id)||chosen===p.id?7:4" vector-effect="non-scaling-stroke" :stroke-dasharray="p.status==='blocked'?'7 6':undefined" :marker-end="p.directed?'url(#arrow2)':undefined"/><text v-if="showLabels&&(state.pipes.length<25||chosen===p.id||preview?.pipes.includes(p.id))" :x="(at(p.from).x+at(p.to).x)/2+6" :y="(at(p.from).y+at(p.to).y)/2-9" :font-size="bounds.w/44">{{p.id}} · {{p.length}}m</text></g><g v-for="n in state.nodes" :key="n.id" class="network-node" @click.stop="chooseNode(n.id)" tabindex="0" @keydown.enter="chooseNode(n.id)"><circle :cx="at(n.id).x" :cy="at(n.id).y" :r="bounds.w/95" :fill="n.id===start?'#147f72':n.id===end?'#ca8b40':list(via).includes(n.id)?'#568cc0':'white'" stroke="#338978" stroke-width="2" vector-effect="non-scaling-stroke"/><text :x="at(n.id).x" :y="at(n.id).y+bounds.w/39" text-anchor="middle" :font-size="bounds.w/46">{{n.id}}{{n.id===start?' 起点':n.id===end?' 终点':''}}</text></g></svg><div class="map-controls"><button @click="zoom=Math.min(4,zoom*1.2)" title="放大"><Plus :size="18"/></button><button @click="zoom=Math.max(.5,zoom/1.2)" title="缩小"><Minus :size="18"/></button><button @click="resetView" title="适应全图"><Maximize :size="18"/></button><button @click="showLabels=!showLabels" title="切换标签"><Layers :size="18"/></button></div><div class="map-attribution" v-if="baseline&&tiles.length">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a></div></div><div class="map-footnote"><span><i/>正常管段</span><span><i class="amber-bg"/>规划路径</span><span><i class="gray-bg"/>暂停通行</span><label v-if="coords.geo"><input type="checkbox" v-model="baseline"/>地面底图</label><span v-else>拓扑坐标 · 管线位置按档案记录</span></div><div v-if="pipe" class="selected-strip"><strong>{{pipe.id}}</strong><span>{{pipe.from}} → {{pipe.to}}</span><span>{{pipe.length}}m · {{pipe.diameter}}mm · {{pipe.material||'未登记'}}</span><button class="text-btn" @click="mode='detail'">编辑管段资料<ArrowRight :size="14"/></button></div></section><aside v-if="!compact" class="panel planning-panel"><div class="segmented"><button :class="{on:mode==='plan'}" @click="mode='plan'">路线规划</button><button :class="{on:mode==='detail'}" @click="mode='detail'">管段资料</button><button :class="{on:mode==='data'}" @click="mode='data'">数据管理</button></div><div class="form-body" v-if="mode==='plan'"><h3>创建巡检路线</h3><label>任务名称<input v-model="name" maxlength="80"/></label><div class="dual"><label>起点<select v-model="start"><option v-for="n in state.nodes" :key="n.id" :value="n.id">{{n.id}} · {{n.label}}</option></select></label><label>终点<select v-model="end"><option v-for="n in state.nodes" :key="n.id" :value="n.id">{{n.id}} · {{n.label}}</option></select></label></div><label>途经检查井（按顺序）<input v-model="via" placeholder="点击图上选择，或输入 J02, J05"/></label><label>避让管段<input v-model="avoid" placeholder="管段编号，以逗号分隔"/></label><div class="dual"><label>最小管径<select v-model="diameter"><option :value="0">不限制</option><option v-for="d in [200,250,300]" :key="d" :value="d">{{d}} mm</option></select></label><label class="check-label"><input type="checkbox" v-model="flow"/>沿登记方向规划</label></div><button class="outline" @click="plan" :disabled="busy||state.nodes.length<2">计算巡检路线<Route :size="17"/></button><div class="route-result" v-if="preview"><small>可通行路径 · {{preview.legs.length}} 个区间</small><h2>{{preview.length}} <small>m</small></h2><p>{{preview.pipes.join(' → ')}}</p><div v-for="(leg,i) in preview.legs" :key="i" class="route-leg">{{i+1}}. {{leg.start}} → {{leg.end}}<strong>{{leg.length}} m</strong></div></div><label>执行人员<select v-model="worker"><option v-for="w in workers.filter(w=>w.enabled)" :key="w.username" :value="w.username">{{w.displayName}} · {{w.area||'未分片区'}}</option></select></label><label>执行设备<select v-model="device"><option v-for="d in state.devices" :key="d.id" :value="d.id">{{d.id}} · {{d.name}}</option></select></label><button class="primary" @click="create" :disabled="busy||!preview||!worker">保存任务，进入审核<Check :size="17"/></button><p class="hint">按管段长度计算有序途经路线，避开停用管段；通行条件由负责人确认。每个井间区间独立组织现场作业。</p></div><div v-else-if="mode==='detail'" class="form-body"><template v-if="selected"><h3>{{selected.id}} 管段资料</h3><p>{{selected.from}} → {{selected.to}}</p><label>长度（米）<input v-model.number="editLength" type="number" min="1"/></label><label>管径（毫米）<input v-model.number="editDiameter" type="number" min="50"/></label><label>材质<input v-model="editMaterial" maxlength="80"/></label><label>状态<select v-model="editStatus"><option value="normal">正常</option><option value="attention">重点关注</option><option value="blocked">暂停通行</option></select></label><label class="check-label"><input v-model="editDirected" type="checkbox"/>仅允许登记方向通行</label><button class="primary" @click="savePipe" :disabled="busy"><Save :size="16"/>保存资料</button></template><p v-else class="empty">点击管段查看或编辑资料</p></div><div v-else class="form-body"><h3>管网资料管理</h3><label>数据来源<input v-model="source" maxlength="400"/></label><label class="check-label"><input type="checkbox" v-model="sample"/>示例数据</label><input ref="fileInput" type="file" accept=".json,.geojson" @change="loadFile" aria-label="上传管网文件"/><button class="primary" @click="importNetwork" :disabled="!importText||busy">确认导入管网</button><button class="outline" @click="exportNetwork">导出管网JSON</button><button class="outline" @click="exportGeo">导出GeoJSON</button><button class="outline" @click="expand" :disabled="busy">载入园区支路示例</button><div class="hint">支持JSON与GeoJSON。检查井用Point，管段用LineString，并包含id、from、to、length、diameter。现有任务关联的编号需要保留。<br><br>地面地图不提供地下排水档案。现场真实数据来自物业、排水单位或授权GIS服务；资料来源单独登记。</div></div></aside></div><PublicNetwork v-if="publicOpen" @close="publicOpen=false"/><Teleport to="body"><div v-if="hover&&tip" class="pipe-tooltip" :style="{left:hover.x+'px',top:hover.y+'px'}" role="tooltip"><div><strong>{{tip.id}} 管段档案</strong><button v-if="pinned" @click="()=>{hover=null;pinned=false;}" aria-label="关闭管段信息"><X :size="16"/></button></div><p>{{tip.from}} → {{tip.to}}</p><dl><dt>长度 / 管径</dt><dd>{{tip.length}} m / {{tip.diameter}} mm</dd><dt>材质</dt><dd>{{tip.material||'未登记'}}</dd><dt>通行状态</dt><dd>{{tip.status==='blocked'?'暂停通行':tip.status==='attention'?'重点关注':'正常'}}</dd><dt>方向</dt><dd>{{tip.directed?'按登记方向':'双向通行'}}</dd></dl><small>{{pinned?'已选中，可在管段资料中编辑':'点击固定信息窗口'}}</small></div></Teleport></div></template>
